changeSet.sql:
-- No resale hold has a split yet only in a database 5a ran against; ending them keeps the CHECK below true. UPDATE reservations SET status = 'RELEASED', ended_at = now() WHERE resale_listing_id IS NOT NULL AND status = 'ACTIVE'; UPDATE resale_holds SET ended_at = now(), end_reason = 'RELEASED' WHERE ended_at IS NULL; UPDATE resale_listings SET status = 'LISTED' WHERE status = 'HELD';
ALTER TABLE reservations ADD COLUMN resale_consented boolean, ADD COLUMN resale_developer_receives numeric(19, 2), ADD COLUMN resale_seller_receives numeric(19, 2), ADD CONSTRAINT chk_reservations_resale_split CHECK (status <> 'ACTIVE' OR resale_listing_id IS NULL OR (resale_consented IS NOT NULL AND resale_developer_receives IS NOT NULL AND resale_seller_receives IS NOT NULL));
ALTER TABLE transactions ADD COLUMN resale_listing_id uuid REFERENCES resale_listings (id), ADD COLUMN resale_of_transaction_id uuid REFERENCES transactions (id), ADD COLUMN resale_developer_receives numeric(19, 2), ADD COLUMN resale_seller_receives numeric(19, 2), ADD CONSTRAINT chk_transactions_resale CHECK ( (resale_listing_id IS NULL) = (resale_of_transaction_id IS NULL) AND (resale_listing_id IS NULL) = (resale_developer_receives IS NULL) AND (resale_listing_id IS NULL) = (resale_seller_receives IS NULL) AND (resale_listing_id IS NULL OR plan = 'OUTRIGHT') AND (resale_listing_id IS NULL OR resale_developer_receives + resale_seller_receives = total_price)); CREATE INDEX idx_transactions_resale_of ON transactions (resale_of_transaction_id) WHERE resale_of_transaction_id IS NOT NULL;
